export class Picard25thCenturyUniformPack
  extends BaseTngEraUniformPack
  implements IUniformPack
{
  constructor() {
    super(UniformEra.Picard25);
  }

  getUniformSwatches(species: Species) {
    if (species === Species.Edosian) {
      return [
        new Swatch(
          BodyType.AverageNonBinary,
          'Average Edosian',
          (token) =>
            UniformCatalog.decorateSwatch(
              this.getUniformAndVariantByBodyType(
                token,
                UniformVariantType.Base,
                BodyType.AverageNonBinary,
              ),
              BodyType.AverageNonBinary,
              token,
            ),
          'Species.edosian',
        ),
      ];
    } else {
      return [
        new Swatch(
          BodyType.AverageMale,
          'Average Male',
          (token) =>
            UniformCatalog.decorateSwatch(
              this.getUniformAndVariantByBodyType(
                token,
                UniformVariantType.Base,
                BodyType.AverageMale,
              ),
              BodyType.AverageMale,
              token,
            ),
          'BodyType.averageMale',
        ),
        new Swatch(
          BodyType.AverageFemale,
          'Average Female',
          (token) =>
            UniformCatalog.decorateSwatch(
              this.getUniformAndVariantByBodyType(
                token,
                UniformVariantType.Base,
                BodyType.AverageFemale,
              ),
              BodyType.AverageFemale,
              token,
            ),
          'BodyType.averageFemale',
        ),
        new Swatch(
          BodyType.AverageNonBinary,
          'Average Non-Binary',
          (token) =>
            UniformCatalog.decorateSwatch(
              this.getUniformAndVariantByBodyType(
                token,
                UniformVariantType.Base,
                BodyType.AverageNonBinary,
              ),
              BodyType.AverageNonBinary,
              token,
            ),
          'BodyType.averageNonBinary',
        ),
      ];
    }
  }

  getUniformVariantSwatches(token: TokenModel) {
    return [];
  }

  getUniformAndVariantBody(token: TokenModel) {
    return this.getUniformAndVariantByBodyType(
      token,
      token.variant,
      token.bodyType,
    );
  }
  getUniformAndVariantByBodyType(
    token: TokenModel,
    variant: UniformVariantType,
    bodyType: BodyType,
  ) {
    if (token.species === Species.Edosian) {
      return (
        this.getNeck(
          bodyType,
          token.skinColor,
          token.species,
          UniformEra.Picard25,
        ) +
        Picard25thCenturyUniforms.averageEdosian
          .replace(DefaultRed, token.divisionColor)
          .replace(
            SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX,
            token.skinColor,
          )
      );
    } else if (bodyType === BodyType.AverageMale) {
      return (
        this.getNeck(
          bodyType,
          token.skinColor,
          token.species,
          UniformEra.Picard25,
        ) +
        Picard25thCenturyUniforms.averageMale
          .replace(DefaultRed, token.divisionColor)
          .replace(
            SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX,
            token.skinColor,
          )
      );
    } else if (bodyType === BodyType.AverageNonBinary) {
      return (
        this.getNeck(
          bodyType,
          token.skinColor,
          token.species,
          UniformEra.Picard25,
        ) +
        Picard25thCenturyUniforms.averageNonBinary
          .replace(DefaultRed, token.divisionColor)
          .replace(
            SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX,
            token.skinColor,
          )
      );
    } else {
      return (
        this.getNeck(
          bodyType,
          token.skinColor,
          token.species,
          UniformEra.Picard25,
        ) +
        Picard25thCenturyUniforms.averageFemale
          .replace(DefaultRed, token.divisionColor)
          .replace(
            SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX,
            token.skinColor,
          )
      );
    }
  }

  getBorderLogo(token: TokenModel): string {
    return Picard25thCenturyUniforms.insignia;
  }

  getRankIndicator(token: TokenModel): string {
    const result = super.getRankIndicator(token);
    return result.replace(/#fbb03b/g, '#fddfb1');
  }

  getRankBorderIndicator(token: TokenModel): string {
    const result = super.getRankBorderIndicator(token);
    return result.replace(/#fbb03b/g, '#fddfb1');
  }
}
